const updateCollaborationPosition = `-- name: UpdateCollaborationPosition :one
UPDATE issue SET position = $1::double precision,
    revision = revision + CASE WHEN position IS DISTINCT FROM $1::double precision THEN 1 ELSE 0 END
WHERE id = $2::uuid AND workspace_id = $3::uuid
  AND ($4::bigint IS NULL OR revision = $4::bigint)
RETURNING id, workspace_id, title, description, status, priority, assignee_type, assignee_id, creator_type, creator_id, parent_issue_id, acceptance_criteria, context_refs, position, due_date, created_at, updated_at, number, project_id, origin_type, origin_id, first_executed_at, start_date, metadata, stage, properties, revision, last_activity_at, admission_status, current_iteration_id, iteration_rollover_count
`

type UpdateCollaborationPositionParams struct {
	Position         float64     `json:"position"`
	IssueID          pgtype.UUID `json:"issue_id"`
	WorkspaceID      pgtype.UUID `json:"workspace_id"`
	ExpectedRevision pgtype.Int8 `json:"expected_revision"`
}

func (q *Queries) UpdateCollaborationPosition(ctx context.Context, arg UpdateCollaborationPositionParams) (Issue, error) {
	row := q.db.QueryRow(ctx, updateCollaborationPosition,
		arg.Position,
		arg.IssueID,
		arg.WorkspaceID,
		arg.ExpectedRevision,
	)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Title,
		&i.Description,
		&i.Status,
		&i.Priority,
		&i.AssigneeType,
		&i.AssigneeID,
		&i.CreatorType,
		&i.CreatorID,
		&i.ParentIssueID,
		&i.AcceptanceCriteria,
		&i.ContextRefs,
		&i.Position,
		&i.DueDate,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Number,
		&i.ProjectID,
		&i.OriginType,
		&i.OriginID,
		&i.FirstExecutedAt,
		&i.StartDate,
		&i.Metadata,
		&i.Stage,
		&i.Properties,
		&i.Revision,
		&i.LastActivityAt,
		&i.AdmissionStatus,
		&i.CurrentIterationID,
		&i.IterationRolloverCount,
	)
	return i, err
}

const workspaceHasCollaborationRecords = `-- name: WorkspaceHasCollaborationRecords :one
SELECT EXISTS (SELECT 1 FROM issue_collaboration c JOIN issue i ON i.id = c.issue_id WHERE i.workspace_id = $1)::boolean
`

func (q *Queries) WorkspaceHasCollaborationRecords(ctx context.Context, workspaceID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, workspaceHasCollaborationRecords, workspaceID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
